<script setup>
import {ref,computed,watch,onMounted,onUnmounted} from 'vue';import {useRouter} from 'vue-router';import PageTitle from '../components/PageTitle.vue';import Icon from '../components/Icon.vue';import Badge from '../components/Badge.vue';import EmptyState from '../components/EmptyState.vue';import CrudForm from '../components/CrudForm.vue';import Modal from '../components/Modal.vue';import {api,mutate,notify,ui} from '../lib/api.js';import {money,dateLabel,paid,progress,sizeLabel,downloadCsv} from '../lib/format.js';import {labels} from '../../shared/contracts.js';
const props=defineProps({type:String});const router=useRouter();
const config={clients:{n:'02',title:'LES CLIENTS',subtitle:'Les relations qui font grandir le studio.',action:'Ajouter un client',statuses:['active','prospect','archived'],columns:['Client / entreprise','Contact','Statut','Projets','Encaissé','Reste à payer','Dernier projet']},quotes:{n:'03',title:'LES DEVIS',subtitle:'Des idées claires. Des engagements précis.',action:'Créer un devis',statuses:['draft','sent','viewed','accepted','declined','expired'],columns:['Référence / objet','Client','Statut','Total TTC','Récurrent / mois','Date','Validité']},projects:{n:'04',title:'LES PROJETS',subtitle:'De la première idée à la mise en ligne.',action:'Nouveau projet',statuses:['pending','waiting','progress','review','changes','completed','delivered','archived'],columns:['Projet / client','Statut','Avancement','Total','Payé','Reste','Livraison']},invoices:{n:'05',title:'LES FACTURES',subtitle:'Chaque prestation a sa trace.',action:'Créer une facture',statuses:['draft','sent','paid','partial','overdue','cancelled'],columns:['Référence / objet','Client','Statut','Total TTC','Payé','Date','Échéance']},expenses:{n:'06',title:'LES DÉPENSES',subtitle:'Gardez la main sur ce qui fait tourner le studio.',action:'Ajouter une dépense',statuses:['paid','pending'],columns:['Fournisseur','Catégorie','Date','HT','TTC','Statut','Pièces']},services:{n:'07',title:'LES PRESTATIONS',subtitle:'Votre savoir-faire. Vos offres. Vos tarifs.',action:'Ajouter une prestation',statuses:['active','inactive'],columns:[]},documents:{n:'08',title:'LES DOCUMENTS',subtitle:'Tous les fichiers, reliés aux bons dossiers.',action:'Ajouter un document',statuses:[],columns:['Document','Type','Dossier associé','Date','Taille']}};
const c=computed(()=>config[props.type]),data=ref({rows:[],count:0}),q=ref(''),status=ref(''),sort=ref('date'),page=ref(1),loading=ref(true),error=ref(''),open=ref(false),editing=ref(null),view=ref(localStorage.getItem('bw-project-view')||'list'),projectModal=ref(false),accepted=ref([]),selectedQuote=ref(''),confirm=ref(null),busy=ref(false);
const pageSize=computed(()=>props.type==='services'||view.value==='kanban'?100:25);const pages=computed(()=>Math.max(1,Math.ceil(data.value.count/pageSize.value)));const categories=computed(()=>[...new Set(data.value.rows.map(s=>s.category?.name))]);const columns=['pending','waiting','progress','review','changes','completed','delivered','archived'];
let timer;async function load(){loading.value=true;try{error.value='';data.value=await api(`/${props.type}?q=${encodeURIComponent(q.value)}&status=${status.value}&sort=${sort.value}&page=${page.value}&limit=${props.type==='services'||view.value==='kanban'?100:25}`);}catch(e){error.value=e.message;}finally{loading.value=false;}}
watch([q,status,sort],()=>{page.value=1;clearTimeout(timer);timer=setTimeout(load,180);});watch([page,()=>ui.revision],load);watch(view,v=>{localStorage.setItem('bw-project-view',v);load();});onMounted(load);onUnmounted(()=>clearTimeout(timer));
async function create(){editing.value=null;if(['quotes','invoices'].includes(props.type))router.push(`/${props.type}/new`);else if(props.type==='projects'){try{accepted.value=(await api('/quotes?status=accepted&limit=100')).rows.filter(q=>!q.project);selectedQuote.value=accepted.value[0]?.id||'';projectModal.value=true;}catch(e){notify(e.message,'error');}}else open.value=true;}
function edit(r){editing.value=r;open.value=true;}
async function convert(){if(!selectedQuote.value)return;busy.value=true;try{const p=await mutate(`/quotes/${selectedQuote.value}/convert`,'POST',{},'Projet créé depuis le devis.');router.push('/projects/'+p.id);}catch(e){notify(e.message,'error');}finally{busy.value=false;}}
function openRecord(r){if(props.type==='services')edit(r);else if(props.type==='documents')window.open(`/api/documents/${r.id}/download`,'_blank','noopener');else router.push(`/${props.type}/${r.id}`);}
async function remove(){busy.value=true;try{await mutate('/documents/'+confirm.value.id,'DELETE',undefined,'Document supprimé.');confirm.value=null;}catch(e){notify(e.message,'error');}finally{busy.value=false;}}
async function changeStatus(id,status){try{await mutate('/projects/'+id,'PATCH',{status},'Statut mis à jour.');}catch(e){notify(e.message,'error');}}
function drop(e,status){const id=e.dataTransfer.getData('text/plain');if(data.value.rows.some(p=>p.id===id))changeStatus(id,status);}
function cells(r){if(props.type==='clients')return [r.name,r.email,{status:r.status},r._count.projects,money(r.paidCents,true),money(r.remainingCents,true),dateLabel(r.lastProject,true)];if(['quotes','invoices'].includes(props.type))return [r.reference,r.client.name,{status:r.status},money(r.totalCents,true),money(props.type==='quotes'?r.recurringCents:paid(r),true),dateLabel(r.issuedDate,true),dateLabel(r.validUntil||r.dueDate,true)];if(props.type==='projects')return [r.title,{status:r.status},{progress:progress(r)},money(r.totalCents,true),money(paid(r),true),money(r.totalCents-paid(r),true),dateLabel(r.dueDate,true)];if(props.type==='expenses')return [r.supplier,r.category,dateLabel(r.date,true),money(r.netCents,true),money(r.totalCents,true),{status:r.paid?'paid':'pending'},r.documents.length];return [r.name,r.mime.split('/')[1],r.project?.title||r.client?.name||r.quote?.reference||r.invoice?.reference||r.expense?.supplier||r.referrer?.name||'Bibliothèque',dateLabel(r.createdAt,true),sizeLabel(r.size)];}
async function exportAll(){busy.value=true;try{let rows=[],p=1,count=Infinity;while(rows.length<count){const r=await api(`/${props.type}?q=${encodeURIComponent(q.value)}&status=${status.value}&page=${p++}&limit=100`);rows.push(...r.rows);count=r.count;if(!r.rows.length)break;}downloadCsv(`birostweb-${props.type}.csv`,['Nom / titre','Référence','Client / contact','Email','Statut','Montant EUR','Date'],rows.map(r=>[r.name||r.title||r.supplier,r.reference,r.client?.name||r.contact,r.email,labels[r.status]||r.status,(Number(r.totalCents??r.unitCents??r.paidCents??0)/100).toFixed(2),r.issuedDate||r.date||r.createdAt]));}catch(e){notify(e.message,'error');}finally{busy.value=false;}}
</script>
<template>
<PageTitle :number="c.n" :title="c.title" :subtitle="c.subtitle"><button class="btn" :disabled="busy" @click="exportAll"><Icon name="Download"/>Exporter</button><button class="btn primary" @click="create"><Icon name="Plus"/>{{c.action}}</button></PageTitle>
<div class="toolbar"><label class="search-field"><Icon name="Search"/><input v-model="q" placeholder="Rechercher…" aria-label="Rechercher dans la liste"></label><div class="toolbar-end"><select v-if="c.statuses.length" v-model="status" aria-label="Filtrer par statut"><option value="">Tous les statuts</option><option v-for="s in c.statuses" :key="s" :value="s">{{s==='inactive'?'Désactivée':s==='pending'&&type==='expenses'?'Non payée':labels[s]}}</option></select><select v-if="type==='clients'" v-model="sort" aria-label="Trier les clients"><option value="date">Plus récents</option><option value="name">Nom A → Z</option></select><div class="segmented" v-if="type==='projects'"><button v-for="[v,i,l] in [['list','List','Liste'],['cards','LayoutGrid','Cartes'],['kanban','FolderKanban','Kanban']]" :key="v" :class="{selected:view===v}" @click="view=v" :aria-label="l"><Icon :name="i" :size="16"/></button></div><RouterLink v-if="type==='invoices'||type==='expenses'" class="btn" :to="`/calendar?mode=archive&type=${type}`"><Icon name="CalendarDays"/>Archives</RouterLink></div></div>
<p v-if="error" class="form-error">{{error}} <button @click="load">Réessayer</button></p><div v-if="loading&&!data.rows.length" class="skeleton-page"></div><EmptyState v-else-if="!data.rows.length" :title="q||status?'Aucun résultat.':'Tout commence ici.'" :description="q||status?'Essayez un autre filtre ou une autre recherche.':'Ajoutez votre premier élément pour commencer.'"><button v-if="!q&&!status" class="btn primary" @click="create">{{c.action}}<Icon name="Plus"/></button></EmptyState>
<template v-else-if="type==='services'"><p class="section-note">Les tarifs affichés viennent de votre catalogue. Les modifications s’appliquent aux prochains devis ; vos documents existants conservent leurs prix.</p><section v-for="category in categories" :key="category"><div class="category-head"><h2>{{category.toUpperCase()}}</h2><span class="eyebrow">{{data.rows.filter(s=>s.category.name===category).length}} PRESTATIONS</span></div><div class="record-cards"><article v-for="s in data.rows.filter(s=>s.category.name===category)" :key="s.id" class="service-card" :class="{inactive:!s.active}"><div class="row-between"><span class="eyebrow muted">{{s.frequency==='once'?'PONCTUEL':'RÉCURRENT'}}</span><Badge :status="s.active?'active':'archived'"/></div><h3>{{s.name}}</h3><p>{{s.description}}</p><div class="service-price"><span v-if="s.indicative">À partir de </span>{{s.pricing==='custom'?'Sur devis':money(s.unitCents,true)}}<span v-if="s.frequency!=='once'"> / {{s.frequency==='monthly'?'mois':'an'}}</span><span v-else-if="s.pricing==='hourly'"> / heure</span></div><footer><small class="muted">{{s.includesMaintenance?'Maintenance incluse':'Tarif HT'}}</small><button class="text-button" @click="edit(s)">Modifier<Icon name="ArrowUpRight" :size="16"/></button></footer></article></div></section></template>
<div v-else-if="type==='projects'&&view==='cards'" class="record-cards"><RouterLink v-for="p in data.rows" :key="p.id" :to="'/projects/'+p.id" class="project-card"><div class="row-between"><span class="eyebrow muted">{{p.reference}}</span><Icon name="ArrowUpRight"/></div><div><h3>{{p.title}}</h3><p>{{p.client.name}}</p></div><Badge :status="p.status"/><div class="progress-track"><i :style="{width:progress(p)+'%'}"></i></div><div class="row-between"><span class="mono">{{money(p.totalCents-paid(p))}} à recevoir</span><span class="table-sub">{{dateLabel(p.dueDate,true)}}</span></div></RouterLink></div>
<div v-else-if="type==='projects'&&view==='kanban'" class="kanban-board"><section v-for="s in columns" :key="s" class="kanban-column" @dragover.prevent @drop.prevent="drop($event,s)"><header>{{labels[s]}}<span class="mono">{{data.rows.filter(p=>p.status===s).length}}</span></header><article v-for="p in data.rows.filter(p=>p.status===s)" :key="p.id" class="project-card" draggable="true" @dragstart="$event.dataTransfer.setData('text/plain',p.id)"><div class="row-between"><span class="eyebrow muted">{{p.client.name}}</span><Icon name="GripVertical" :size="14"/></div><RouterLink :to="'/projects/'+p.id"><h3>{{p.title}}</h3></RouterLink><div class="row-between"><span class="mono">{{money(p.totalCents)}}</span><RouterLink :to="'/projects/'+p.id" aria-label="Ouvrir le projet"><Icon name="ArrowUpRight"/></RouterLink></div><select :value="p.status" @change="changeStatus(p.id,$event.target.value)" :aria-label="`Statut de ${p.title}`"><option v-for="s in columns" :value="s" :key="s">{{labels[s]}}</option></select></article></section></div>
<div v-else class="panel"><div class="table-scroll"><table><thead><tr><th v-for="col in c.columns" :key="col">{{col.toUpperCase()}}</th><th></th></tr></thead><tbody><tr v-for="r in data.rows" :key="r.id"><td v-for="(cell,i) in cells(r)" :key="i"><template v-if="i===0"><button class="table-title" @click="openRecord(r)">{{cell}}</button><div class="table-sub">{{r.title&&type!=='projects'?r.title:type==='projects'?r.client.name:type==='clients'?r.contact:''}}</div></template><Badge v-else-if="cell?.status" :status="cell.status"/><div v-else-if="typeof cell==='object'&&cell.progress!==undefined" class="progress-cell"><div class="progress-track"><i :style="{width:cell.progress+'%'}"></i></div>{{cell.progress}}%</div><template v-else>{{cell}}</template></td><td><button class="icon-button" @click="openRecord(r)" :aria-label="`Ouvrir ${r.name||r.title||r.supplier}`"><Icon :name="type==='documents'?'Download':'ArrowUpRight'"/></button><button v-if="type==='documents'" class="icon-button" @click="confirm=r" aria-label="Supprimer"><Icon name="Trash2"/></button></td></tr></tbody></table></div><footer class="pagination"><span>{{data.count}} résultat{{data.count>1?'s':''}}</span><div><button class="icon-button outlined" :disabled="page===1" @click="page--" aria-label="Page précédente"><Icon name="ChevronLeft"/></button><span>{{page}} / {{pages}}</span><button class="icon-button outlined" :disabled="page>=pages" @click="page++" aria-label="Page suivante"><Icon name="ChevronRight"/></button></div></footer></div>
<footer v-if="(type==='services'||(type==='projects'&&view!=='list'))&&pages>1" class="pagination"><span>{{data.count}} résultats</span><div><button class="icon-button" :disabled="page===1" @click="page--" aria-label="Page précédente"><Icon name="ChevronLeft"/></button><span>{{page}} / {{pages}}</span><button class="icon-button" :disabled="page>=pages" @click="page++" aria-label="Page suivante"><Icon name="ChevronRight"/></button></div></footer><CrudForm :open="open" :kind="type" :record="editing" @close="open=false" @saved="load"/><Modal :open="projectModal" title="DU DEVIS AU PROJET." @close="projectModal=false"><form @submit.prevent="convert"><p class="muted">Le projet reprendra les prestations, les prix, les options et les notes du devis accepté.</p><label v-if="accepted.length">Devis accepté<select v-model="selectedQuote"><option v-for="q in accepted" :key="q.id" :value="q.id">{{q.reference}} · {{q.client.name}} · {{q.title}}</option></select></label><EmptyState v-else title="Aucun devis à convertir." description="Acceptez d’abord un devis depuis sa fiche."><RouterLink class="btn" to="/quotes">Voir les devis</RouterLink></EmptyState><button v-if="accepted.length" class="btn primary" :disabled="busy">Créer le projet<Icon name="ArrowRight"/></button></form></Modal><Modal :open="!!confirm" title="SUPPRIMER CE DOCUMENT ?" @close="confirm=null"><p>« {{confirm?.name}} » sera supprimé du stockage. Cette action est définitive.</p><div class="form-actions"><button class="btn" @click="confirm=null">Conserver</button><button class="btn danger" @click="remove" :disabled="busy">Supprimer</button></div></Modal>
</template>
